# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ORUCUN BİREYE VE TOPLUMA KAZANDIRDIKLARI (DKAB.6.2.3)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İrade ve Sabır Eğitimi</text>\n  <text x="125" y="100" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Nefsin isteklerine sınır koyar</text>\n  <text x="125" y="124" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Öz denetim becerisini güçlendirir</text>\n  <text x="125" y="148" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Kötü söz ve davranıştan korur</text>\n  <text x="125" y="172" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Zorluklara karşı sabrı öğretir</text>\n  <text x="125" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">«Oruç bir kalkandır.» (Hadis-i Şerif)</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Empati ve Şükür Bilinci</text>\n  <text x="350" y="100" text-anchor="middle" font-size="11.5" fill="#14532d">• Aç ve yoksulun hâlini anlama</text>\n  <text x="350" y="124" text-anchor="middle" font-size="11.5" fill="#14532d">• Nimetlerin kıymetini fark etme</text>\n  <text x="350" y="148" text-anchor="middle" font-size="11.5" fill="#14532d">• İsraftan ve savurganlıktan kaçınma</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11.5" fill="#14532d">• Allah\'a (cc) şükür duyarlılığı</text>\n  <text x="350" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Nimetin Değerini Bilmek</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Yardımlaşma ve Kardeşlik</text>\n  <text x="575" y="100" text-anchor="middle" font-size="11.5" fill="#713f12">• Fitre, zekât ve sadaka paylaşımı</text>\n  <text x="575" y="124" text-anchor="middle" font-size="11.5" fill="#713f12">• İftar sofralarında buluşma</text>\n  <text x="575" y="148" text-anchor="middle" font-size="11.5" fill="#713f12">• Merhamet ve cömertlik artışı</text>\n  <text x="575" y="172" text-anchor="middle" font-size="11.5" fill="#713f12">• Toplumsal birlik ve huzur</text>\n  <text x="575" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Paylaştıkça Çoğalan Bereket</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KÜLTÜRÜMÜZDE RAMAZAN VE ORUÇ GELENEKLERİ</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">İbadet ve Kur\'an Geleneğimiz</text>\n  <text x="40" y="98" font-size="12" fill="#831843">• Sahur ve İmsak: Bereketli gece hazırlığı</text>\n  <text x="40" y="122" font-size="12" fill="#831843">• İftar Sofraları: Dua ve paylaşma vakti</text>\n  <text x="40" y="146" font-size="12" fill="#831843">• Teravih Namazı: Yatsıdan sonra 20 rekât</text>\n  <text x="40" y="170" font-size="12" fill="#831843">• Mukabele: Karşılıklı Kur\'an okuma sünneti</text>\n  <text x="40" y="194" font-size="12" fill="#831843">• Kadir Gecesi: Bin aydan daha hayırlı gece</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9d174d">Kur\'an Ayı Ramazan</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Kültürel Mirasımız ve Geleneklerimiz</text>\n  <text x="380" y="98" font-size="12" fill="#581c87">• Mahya: Minareler arası ışıklı güzel sözler</text>\n  <text x="380" y="122" font-size="12" fill="#581c87">• Diş Kirası: İftara gelen misafire hediye</text>\n  <text x="380" y="146" font-size="12" fill="#581c87">• Tekne Orucu: Çocukları oruca alıştırma</text>\n  <text x="380" y="170" font-size="12" fill="#581c87">• Zimem Defteri: Veresiye borçlarını kapatma</text>\n  <text x="380" y="194" font-size="12" fill="#581c87">• Ramazan Davulcusu ve Manileri · Pide ve Güllaç</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">İncelik ve Zarafet Medeniyeti</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTE GENEL ÖZET TABLOSU: RAMAZAN VE ORUÇ</text>\n  <rect x="25" y="48" width="650" height="92" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Oruç İbadetinin Temel Unsurları ve Çeşitleri</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" fill="#155e75">• Vakit: İmsak (fecr-i sadık) ile başlar, güneşin batmasıyla (iftar/akşam ezanı) sona erer.</text>\n  <text x="350" y="122" text-anchor="middle" font-size="12" fill="#155e75">• Çeşitleri: Farz (Ramazan), Vacip (Adak ve bozulan nafilenin kazası), Nafile (Aşure, Pazartesi-Perşembe, Davud orucu).</text>\n\n  <rect x="25" y="152" width="650" height="90" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Ünitenin Peygamber Kıssası ve Suresi</text>\n  <text x="350" y="202" text-anchor="middle" font-size="12" fill="#9a3412">• Hz. Davud (as): Kendisine Zebur verilmiş, demiri yumuşatıp zırh yaparak el emeğiyle geçinmiş, adaletle hükmetmiştir.</text>\n  <text x="350" y="226" text-anchor="middle" font-size="12" fill="#9a3412">• Fil Suresi (5 ayet): Kâbe\'yi yıkmaya gelen Ebrehe\'nin fil ordusunun ebabil kuşlarıyla helak edilişini anlatır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
